interface Org {
  id?: string;
  name?: string;
  [key: string]: unknown;
}

interface User {
  id?: string;
  orgId: string;
  org?: Org;
  [key: string]: unknown;
}

async function loadUser(id: string): Promise<User> {
  const response = await fetch(`/api/users/${id}`);
  if (!response.ok) {
    throw new Error(`Bad status ${response.status}`);
  }

  const user = (await response.json()) as User;

  const orgResponse = await fetch(`/api/orgs/${user.orgId}`);
  if (!orgResponse.ok) {
    throw new Error(`Bad status ${orgResponse.status}`);
  }

  user.org = (await orgResponse.json()) as Org;
  return user;
}

async function loadUsers(ids: string[]): Promise<User[]> {
  return Promise.all(ids.map((id) => loadUser(id)));
}

export { loadUser, loadUsers };

